"""duck_drive.py

Shared joystick-to-command synthesis for both:
  - simulator (mujoco_infer.py)
  - runtime (RLWalk.py)

This sits ABOVE the low-level PuddleJoy driver:
  - PuddleJoy: reads /dev/input/* and provides Controller + ControllerEvent objects
  - DuckDrive: interprets those events into the policy command vector, with smoothing/blending

Key features:
  - No hard-coded command indices: derive indices/ranges from the ONNX policy metadata.
  - YAML-configurable behavior, with safe defaults.
  - Button -> virtual state/action mappings with short-press vs long-press.

Notes on button mappings:
  - Short press triggers on *release* (so we can distinguish short vs long).
  - Long press is a held state: activates after hold_s seconds and stays active while held.

"""

from __future__ import annotations

from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple

import math
import os
import time
import inspect

try:
    from .emote_player import EmotePlayer
except ImportError:  # pragma: no cover - direct script/import fallback
    from emote_player import EmotePlayer

try:
    import yaml  # PyYAML
except Exception:  # pragma: no cover
    yaml = None


# -----------------
# small utilities
# -----------------

def _clamp(v: float, lo: float, hi: float) -> float:
    return lo if v < lo else hi if v > hi else v


def _apply_deadzone(v: float, dz: float) -> float:
    return 0.0 if abs(v) < dz else v


def _shape(v: float, exponent: float) -> float:
    # v assumed within [-1, 1]
    a = abs(v)
    if a <= 0.0:
        return 0.0
    return math.copysign(a ** exponent, v)


def _alpha_from_tau(dt: float, tau_s: float) -> float:
    # alpha = 1 - exp(-dt/tau). Guard small/zero tau.
    if tau_s <= 0.0:
        return 1.0
    dt = max(0.0, dt)
    return 1.0 - math.exp(-dt / tau_s)


def _load_yaml(path: str | Path) -> Dict[str, Any]:
    if yaml is None:
        raise RuntimeError("PyYAML is not installed; cannot load YAML config.")
    p = Path(path)
    if not p.exists():
        raise FileNotFoundError(str(p))
    data = yaml.safe_load(p.read_text()) or {}
    if not isinstance(data, dict):
        raise ValueError(f"Expected mapping at YAML root, got {type(data)}")
    return data


# -----------------
# policy helpers
# -----------------

def _policy_index(policy: Any, name: str) -> Optional[int]:
    """Best-effort command index lookup for different policy wrappers."""
    if policy is None:
        return None
    idx = policy.command_index.get(name)
    return int(idx) if idx is not None else None


def _policy_range(policy: Any, which: str, default: Tuple[float, float] = (-1.0, 1.0)) -> Tuple[float, float]:
    # which in {"x","y","theta"}
    attr = {
        "x": "COMMANDS_RANGE_X",
        "y": "COMMANDS_RANGE_Y",
        "theta": "COMMANDS_RANGE_THETA",
    }.get(which, None)

    if attr and hasattr(policy, attr):
        try:
            r = getattr(policy, attr)
            if isinstance(r, (list, tuple)) and len(r) == 2:
                return (float(r[0]), float(r[1]))
        except Exception:
            pass

    return (float(default[0]), float(default[1]))


def _scale_unit_to_range(v_unit: float, r: Tuple[float, float]) -> float:
    """Map v_unit in [-1, 1] to asymmetric range r=(lo, hi).

    Keeps 0 -> 0, positive uses hi, negative uses lo.
    """
    lo, hi = float(r[0]), float(r[1])
    if v_unit >= 0.0:
        return v_unit * hi
    # lo is expected <= 0; if someone passes positive lo, still behave sensibly
    return v_unit * abs(lo) if lo < 0.0 else v_unit * lo


# -----------------
# config
# -----------------

@dataclass
class DuckDriveConfig:
    # input shaping
    deadzone: float = 0.015
    response_exponent: float = 1.5

    # command smoothing (time-based)
    cmd_tau_s: float = 0.03
    cmd_eps: float = 1e-3

    # head trailing filter (time-based)
    head_trail_tau_s: float = 0.20  # larger = slower trailing

    # Trunk command output smoothing (time-based).
    # These are applied after torso assist, idle animations, and walking
    # suppression are resolved, just before writing trunk_*_cmd channels.
    # None preserves the legacy behavior: trunk uses cmd_tau_s, or
    # walk_trunk_restore_tau_s when walking suppression is enabled.
    trunk_tau_s: Optional[float] = None
    trunk_pitch_tau_s: Optional[float] = None
    trunk_yaw_tau_s: Optional[float] = None
    trunk_roll_tau_s: Optional[float] = None

    # torso assist (based on gaze deflection)
    torso_onset: float = 0.60
    torso_gain_pitch: float = 1.00
    torso_gain_yaw: float = 1.00
    torso_gain_roll: float = 1.00

    # head/neck pitch inversion blend (for safe-ish behavior)
    pitch_invert_thresh: float = -0.4
    pitch_invert_width: float = 0.3

    # head yaw limiting when trunk is pitched down (helps avoid extreme down+yaw combos)
    # onset in unit trunk_pitch_u where yaw limiting begins (0..1).
    head_yaw_limit_pitch_onset: float = 0.0
    # yaw scale applied at max downward trunk pitch (1.0 disables).
    head_yaw_limit_min_scale: float = 1.0

    # Forward pitch behavior (stick forward / positive pitch)
    #   1) Neck extends first.
    #   2) Then head pitches down.
    #   3) Then trunk pitches down.
    #
    # forward_neck_full_at is the fraction of joystick travel at which the neck reaches full extension.
    # Example: 0.65 means: first 65% = extend neck, remaining 35% = head/trunk phases.
    forward_neck_full_at: float = 0.50
    forward_head_down_gain: float = 1.0
    forward_head_down_exponent: float = 1.0

    # Forward pitch "phase-back" smoothing:
    # When the stick is released, keep walking BACK down the same phases (trunk -> head -> neck)
    # instead of instantly switching to the neutral/negative mapping at pitch_u_in == 0.
    # - attack tau: how fast u rises when pushing forward
    # - release taus: how fast u decays when releasing, per phase
    forward_u_attack_tau_s: float = 0.0
    forward_u_release_tau_neck_s: float = 0.0
    forward_u_release_tau_head_s: float = 0.0
    forward_u_release_tau_trunk_s: float = 0.0



    # Forward trunk boost (NOT part of stick range):
    # The trunk pitches down automatically after the stick has been held near full-forward
    # for some time. On release, trunk returns first (slowly), and only then do we allow
    # head/neck to walk back down their range.
    forward_trunk_enable: bool = True
    forward_trunk_arm_u: float = 0.98
    forward_trunk_hold_s: float = 0.25
    forward_trunk_u_max: float = 1.0
    forward_trunk_down_tau_s: float = 0.35
    forward_trunk_up_tau_s: float = 0.80
    forward_trunk_release_gate_u: float = 0.25

    # Walking + trunk suppression:
    # The locomotion policy is not trained with trunk-command modifiers while
    # walking. Keep head/neck user control active, but smoothly drive trunk
    # commands back to zero whenever walking/base-motion commands are active.
    disable_trunk_while_walking: bool = True
    # Walking detection threshold in unit command space (after deadzone/shaping).
    walk_trunk_motion_thresh: float = 0.05
    # When entering walking, ease trunk commands toward zero with this time constant.
    walk_trunk_zero_tau_s: float = 0.20
    # When returning to idle, re-enable trunk commands with this time constant.
    walk_trunk_restore_tau_s: float = 0.08

    # wiggle state defaults
    wiggle_freq_hz: float = 2.0
    wiggle_trunk_amp: float = 1.0
    wiggle_head_amp: float = 0.5

    # trunk_wiggle state defaults
    trunk_wiggle_freq_hz: float = 2.0
    trunk_wiggle_trunk_amp: float = 1.0
    trunk_wiggle_head_amp: float = 0.5

    # trunk_wiggle state defaults
    trunk_roll_freq_hz: float = 2.0
    trunk_roll_trunk_amp: float = 1.0
    trunk_roll_head_amp: float = 0.5

    # head nod state defaults
    head_nod_freq_hz: float = 2.0
    head_nod_amp: float = 1.0

    # Data-driven one-shot emotes.  By default DuckDrive scans an ``emotes``
    # directory next to this module and another next to config_yaml.
    emote_dirs: List[str] = field(default_factory=list)
    # Full physical height span represented by the policy command range.  None
    # auto-detects it from exported metadata/reference paths.
    emote_height_range_cm: Optional[float] = None
    emote_interpolate: bool = True
    # feet_planted may suppress the separate march/walk-in-place request, but
    # live lin_vel_x/lin_vel_y/ang_vel_yaw always pass through the overlay.
    emote_suppress_walk_in_place_for_feet_planted: bool = True
    # Deprecated alias retained for configs written for the first bundle.
    emote_zero_base_for_feet_planted: Optional[bool] = None
    emote_trigger_named_buttons: bool = True
    emote_debug: bool = False
    # Authored body-channel coordinate transform after channel remapping
    # (lean->pitch, tilt->roll, twist->yaw).  The source clips already pair
    # body_twist with head_yaw for physical counter-rotation, so yaw preserves
    # the authored sign.  Pitch retains DuckDrive's existing inversion.
    emote_trunk_signs: Dict[str, float] = field(
        default_factory=lambda: {
            "body_lean": -1.0,
            "body_tilt": 1.0,
            "body_twist": 1.0,
        }
    )

    # long-press behavior
    long_press_default_s: float = 1.0

    # strafe synthesis
    lb_rb_rate: float = 0.02
    lb_rb_decay: float = 0.9
    height_step: float = 0.25

    # Height button auto-repeat (used only when the controller has no analog
    # "height" axis and we synthesize height from buttons / D-pad).
    #
    # Behavior:
    #   - Tap taller/smaller: one step.
    #   - Hold taller/smaller: keep stepping after an initial delay.
    height_repeat_delay_s: float = 0.25
    height_repeat_period_s: float = 0.08

    # Posture mode: a latched/toggled "posture" state makes the duck stand in
    # place while the left stick directly poses the trunk.  Height is latched
    # and stepped only when the left stick is held near the top/bottom extent.
    posture_latched: bool = True
    posture_button: str = "posture"
    # FrSky/drive mappings use the left-stick vertical axis with the opposite
    # sign from the trunk-pitch command convention, so direct posture pitch is
    # inverted by default.
    posture_trunk_pitch_invert: bool = True
    posture_height_step: float = 0.25
    posture_height_edge: float = 0.93
    posture_height_release_edge: float = 0.82
    # Dwell before the first height step after entering the stick extent.
    # Prevents accidental height changes when the operator only wants maximum
    # trunk pitch for a pose. Set to 0.0 for immediate first-step behavior.
    posture_height_initial_delay_s: float = 0.12
    posture_height_repeat_delay_s: float = 0.08
    posture_height_repeat_period_s: float = 0.08
    # While the left-stick vertical axis is being used as the posture height
    # step trigger, blend direct trunk pitch back toward neutral.  This lets the
    # operator raise/lower the body without also holding a full trunk lean.
    posture_height_level_trunk_pitch: bool = True
    posture_height_level_trunk_pitch_blend: float = 1.0
    posture_zero_recover: bool = True

    # controller switching / polling
    max_events_per_update: int = 8
    axis_activity_eps: float = 0.02
    active_timeout_s: float = 2.0

    # Events with these names do NOT affect controller "active" selection.
    # Useful for "background" controls like /audio/volume.
    ignore_activity_axes: List[str] = field(default_factory=list)
    ignore_activity_buttons: List[str] = field(default_factory=list)

    # scaling applied after mapping [-1,1] -> policy ranges
    scale_lin_vel_x: float = 1.0
    scale_lin_vel_y: float = 1.0
    scale_ang_vel_yaw: float = 1.0

    @classmethod
    def from_yaml(cls, path: Optional[str | Path]) -> "DuckDriveConfig":
        cfg = cls()
        if path is None:
            return cfg
        data = _load_yaml(path)
        dd = data.get("duckdrive", data)
        if not isinstance(dd, dict):
            return cfg
        for field_name in cls.__dataclass_fields__.keys():
            if field_name in dd:
                setattr(cfg, field_name, dd[field_name])

        # Friendly config forms:
        #   emote_dir: emotes
        #   emotes: {dirs: [...], height_range_cm: 9.0, debug: true}
        if "emote_dir" in dd and "emote_dirs" not in dd:
            raw_dir = dd.get("emote_dir")
            cfg.emote_dirs = list(raw_dir) if isinstance(raw_dir, (list, tuple)) else [raw_dir]

        emotes = dd.get("emotes")
        if isinstance(emotes, dict):
            aliases = {
                "dir": "emote_dirs",
                "dirs": "emote_dirs",
                "height_range_cm": "emote_height_range_cm",
                "interpolate": "emote_interpolate",
                "suppress_walk_in_place_for_feet_planted": (
                    "emote_suppress_walk_in_place_for_feet_planted"
                ),
                # Legacy key: no longer zeroes X/Y/yaw. It controls only the
                # separate walk-in-place/march suppression behavior.
                "zero_base_for_feet_planted": "emote_zero_base_for_feet_planted",
                "trigger_named_buttons": "emote_trigger_named_buttons",
                "debug": "emote_debug",
                "trunk_signs": "emote_trunk_signs",
            }
            for source, target in aliases.items():
                if source not in emotes:
                    continue
                value = emotes[source]
                if target == "emote_dirs":
                    value = list(value) if isinstance(value, (list, tuple)) else [value]
                setattr(cfg, target, value)
        return cfg


# -----------------
# DuckDrive
# -----------------

class DuckDrive:
    """High-rate command synthesis from joystick events.

    Expected policy API:
      - command_size or commands length
      - command_index dict OR index(name) method
      - COMMANDS_RANGE_X/Y/THETA attributes for velocity ranges (optional)

    Button mapping model (from YAML):

      duckdrive:
        long_press_default_s: 1.0
        button_map:
          reset:
            long_press: {state: trunk_wiggle, hold_s: 1.0}
          push:
            short_press: {toggle_state: neck_lock}
            long_press:  {state: wiggle, hold_s: 1.0}
        states:
          neck_lock:
            min_neck: 0.70
            neck_softness: 0.0
            head_pitch_gain: 1.0
            head_pitch_invert: true

    """

    def __init__(
        self,
        *,
        policy: Any,
        controllers: List[Any],
        commands: Optional[Any] = None,
        config: Optional[DuckDriveConfig] = None,
        config_yaml: Optional[str | Path] = None,
        engaged: bool = True
    ):
        print("DUCKDRIVE")
        self.policy = policy
        self.controllers = list(controllers or [])

        self.warbler = None
        self.cfg = config or DuckDriveConfig.from_yaml(config_yaml)

        self._axes_engaged = engaged
        self._axis_settle_until_t = 0.0

        # keep the raw duckdrive yaml dict for non-dataclass options (button_map/states)
        self._duckdrive_dict: Dict[str, Any] = {}
        if config_yaml is not None:
            try:
                raw = _load_yaml(config_yaml)
                dd = raw.get("duckdrive", raw)
                if isinstance(dd, dict):
                    self._duckdrive_dict = dd
            except Exception:
                self._duckdrive_dict = {}

        # command vector (owned or borrowed)
        if commands is None:
            import numpy as np  # local import
            commands = np.zeros(policy.command_size, dtype=np.float32)
        self.commands = commands
        self.imitation_phase_speed = 1.0

        # indices into commands (derived from policy)
        self.idx_lin_x = _policy_index(policy, "lin_vel_x")
        self.idx_lin_y = _policy_index(policy, "lin_vel_y")
        self.idx_yaw = _policy_index(policy, "ang_vel_yaw")
        self.idx_height = _policy_index(policy, "height")
        self.idx_neck_pitch = _policy_index(policy, "neck_pitch")
        self.idx_head_pitch = _policy_index(policy, "head_pitch")
        self.idx_head_yaw = _policy_index(policy, "head_yaw")
        self.idx_head_roll = _policy_index(policy, "head_roll")
        self.idx_trunk_pitch = _policy_index(policy, "trunk_pitch_cmd")
        self.idx_trunk_yaw = _policy_index(policy, "trunk_yaw_cmd")
        self.idx_trunk_roll = _policy_index(policy, "trunk_roll_cmd")
        self.idx_recover = _policy_index(policy, "recover")
        if self.idx_recover is None:
            self.idx_recover = _policy_index(policy, "walk_in_place")
        self.walk_in_place_enable = self.policy.walk_in_place_enable

        # ranges for velocity channels
        self.range_x = _policy_range(policy, "x", (-1.0, 1.0))
        self.range_y = _policy_range(policy, "y", (-1.0, 1.0))
        self.range_theta = _policy_range(policy, "theta", (-1.0, 1.0))

        # Base locomotion is never owned by the emote overlay. Keep an index
        # guard here as defense in depth, independent of JSON/channel parsing.
        self._emote_passthrough_indices = {
            int(idx)
            for idx in (self.idx_lin_x, self.idx_lin_y, self.idx_yaw)
            if idx is not None
        }

        # Data-driven emote playback. The underlay keeps joystick synthesis
        # independent from the temporary animation overlay: each update restores
        # the previous joystick values, synthesizes the latest operator pose,
        # then uses that live pose as animation-space zero for the next frame.
        self._emote_underlay: Dict[int, float] = {}
        self._emote_channel_handlers: Dict[str, List[Any]] = {}
        self._emote_show_active_channels: set[str] = set()
        self._emote_last_show_values: Dict[str, float] = {}
        suppress_walk_in_place = bool(
            getattr(
                self.cfg,
                "emote_suppress_walk_in_place_for_feet_planted",
                True,
            )
        )
        legacy_zero_base = getattr(
            self.cfg,
            "emote_zero_base_for_feet_planted",
            None,
        )
        if legacy_zero_base is not None:
            suppress_walk_in_place = bool(legacy_zero_base)

        self.emote_player = EmotePlayer(
            policy=policy,
            search_dirs=self._resolve_emote_search_dirs(config_yaml),
            height_range_cm=getattr(self.cfg, "emote_height_range_cm", None),
            trunk_channel_signs=getattr(self.cfg, "emote_trunk_signs", None),
            interpolate=bool(getattr(self.cfg, "emote_interpolate", True)),
            suppress_walk_in_place_for_feet_planted=suppress_walk_in_place,
            debug=bool(getattr(self.cfg, "emote_debug", False)),
        )

        # per-controller state
        self._state = {
            c: {
                "prev_dy": 0.0,
                "height_state": 0.0,
                # Auto-repeat schedule for virtual height buttons.
                "taller_next_t": 0.0,
                "smaller_next_t": 0.0,
                "lin_vel_y_state": 0.0,
                "posture_height_state": 0.0,
                "posture_height_next_t": 0.0,
                "posture_height_dir": 0,
                "posture_height_first_done": False,
                "posture_was_active": False,
                "last_axis": {},
                "last_activity": 0.0,
                "prev_buttons": {},
            }
            for c in self.controllers
        }
        self._last_event = {c: None for c in self.controllers}
        self._active = None
        self._last_update_t = None
        self._current_update_t: Optional[float] = None
        self._posture_active_cached = False

        # head trailing state (global)
        self._head_pitch_cmd = 0.0
        self._head_yaw_cmd = 0.0
        self._head_roll_cmd = 0.0
        self._head_trail_init = False

        # forward pitch phase-back state (positive pitch mapping)
        self._fwd_pitch_u = 0.0
        self._fwd_pitch_u_init = False


        # forward trunk boost state (time-based, independent of stick range)
        self._fwd_trunk_u = 0.0
        self._fwd_trunk_hold_s = 0.0
        self._fwd_trunk_init = False
        # wiggle phase
        self._wiggle_phase = 0.0
        self._wiggle_last_t = time.time()

        # pressed events queue (consumer decides what these mean)
        self._pressed: List[str] = []

        # -----------------
        # Optional event handlers (side-effects that should NOT change active controller)
        # -----------------
        self._ignore_activity_axes = set(str(x) for x in (getattr(self.cfg, "ignore_activity_axes", None) or []))
        self._ignore_activity_buttons = set(str(x) for x in (getattr(self.cfg, "ignore_activity_buttons", None) or []))

        # Handlers keyed by logical control name (ControllerEvent.name).
        #   - axis handlers receive a float value (scaled via ev.get_axis(name))
        #   - button handlers receive a bool pressed/released
        self._axis_handlers: Dict[str, List[Dict[str, Any]]] = {}
        self._button_handlers: Dict[str, List[Dict[str, Any]]] = {}

        # ---------------
        # Virtual mapping: button -> state/action
        # ---------------
        self._button_map: Dict[str, Any] = {}
        bm = self._duckdrive_dict.get("button_map")
        if isinstance(bm, dict):
            self._button_map = bm

        self._has_button_map = bool(self._button_map)
        self._mapped_buttons = list(self._button_map.keys())

        # Track press/hold timing per mapped button
        #   down: current logical pressed state
        #   t_down: time when went down
        #   long_active: whether long_press has fired for this press
        #   long_state: which long_press state is currently being held (if any)
        self._btn_track: Dict[str, Dict[str, Any]] = {
            b: {"down": False, "t_down": 0.0, "long_active": False, "long_state": None}
            for b in self._mapped_buttons
        }

        # virtual states
        self._toggle_states: Dict[str, bool] = {}
        self._hold_counts: Dict[str, int] = {}

        # neck lock state specifics
        self._neck_lock_value: float = 0.0
        self._neck_lock_head_value: float = 0.0
        self._neck_lock_cfg: Dict[str, Any] = {
            "min_neck": 0.70,
            "neck_softness": 0.0,
            "head_pitch_gain": 1.0,
            "head_pitch_invert": True,
        }
        stcfg = self._duckdrive_dict.get("states")
        if isinstance(stcfg, dict):
            nlc = stcfg.get("neck_lock")
            if isinstance(nlc, dict):
                self._neck_lock_cfg.update(nlc)

        # jump state specifics (one-shot): drive height -> +1 quickly, then auto-clear.
        self._jump_cfg: Dict[str, Any] = {
            # Multiplier on the normal command smoothing alpha for height while jumping.
            # Larger = faster (>= ~10 will often feel like a snap).
            "gain": 10.0,
            # Auto-clear once |height-1| <= done_eps.
            "done_eps": 0.02,
        }
        if isinstance(stcfg, dict):
            jc = stcfg.get("jump")
            if isinstance(jc, dict):
                self._jump_cfg.update(jc)

        # height_center state specifics (one-shot): drive height -> target smoothly, then auto-clear.
        self._height_center_cfg: Dict[str, Any] = {
            # Multiplier on the normal height smoothing alpha while centering.
            # Smaller = slower (e.g. 0.2), 1.0 = normal speed.
            "gain": 0.25,
            # Target height in unit space.
            "target": 0.0,
            # Auto-clear once |height-target| <= done_eps.
            "done_eps": 0.02,
        }
        if isinstance(stcfg, dict):
            hc = stcfg.get("height_center")
            if isinstance(hc, dict):
                self._height_center_cfg.update(hc)

        # debug/status
        self.last_strafe_source = ""
        self.last_active_name = ""

    def _resolve_emote_search_dirs(
        self,
        config_yaml: Optional[str | Path],
    ) -> List[Path]:
        """Return emote directories in priority order, de-duplicated."""
        config_base = None
        if config_yaml is not None:
            try:
                config_base = Path(config_yaml).expanduser().resolve().parent
            except Exception:
                config_base = None

        raw_dirs: List[Any] = []

        env_dirs = os.environ.get("PUDDLEDUCK_EMOTE_DIR", "")
        if env_dirs:
            raw_dirs.extend(part for part in env_dirs.split(os.pathsep) if part)

        configured = getattr(self.cfg, "emote_dirs", None) or []
        if isinstance(configured, (str, Path)):
            configured = [configured]
        raw_dirs.extend(configured)

        # The operator-owned library is canonical for robot-specific emotes.
        raw_dirs.append(Path.home() / "emotes")

        # A project-local emotes directory next to the controller config is also
        # useful for development checkouts when the config is not in $HOME.
        if config_base is not None:
            raw_dirs.append(config_base / "emotes")

        # Package defaults: pd/common/emotes.
        raw_dirs.append(Path(__file__).resolve().parent / "emotes")

        out: List[Path] = []
        seen = set()
        for raw in raw_dirs:
            if raw is None:
                continue
            path = Path(os.path.expandvars(os.path.expanduser(str(raw))))
            if not path.is_absolute() and config_base is not None:
                path = config_base / path
            try:
                path = path.resolve()
            except Exception:
                continue
            key = str(path)
            if key in seen:
                continue
            seen.add(key)
            out.append(path)
        return out

    def _zero_commands(self) -> None:
        try:
            self.commands[:] = 0.0
        except Exception:
            pass

    def _reset_axis_synthesis_state(self, *, reset_commands: bool = True) -> None:
        """
        Reset only the command/axis synthesis side.

        Do not clear self._pressed here; buttons are not the problem and RLWalk
        owns the pressed-event queue through pop_pressed().
        """
        self.stop_emote()
        if reset_commands:
            self._zero_commands()

        self._active = None
        self.last_active_name = ""
        self.last_strafe_source = ""
        self._last_event = {c: None for c in self.controllers}

        for st in self._state.values():
            st["last_axis"] = {}
            st["last_activity"] = 0.0
            st["prev_dy"] = 0.0
            st["height_state"] = 0.0
            st["lin_vel_y_state"] = 0.0
            st["taller_next_t"] = 0.0
            st["smaller_next_t"] = 0.0
            st["posture_height_state"] = 0.0
            st["posture_height_next_t"] = 0.0
            st["posture_height_dir"] = 0
            st["posture_height_first_done"] = False
            st["posture_was_active"] = False

        self._head_pitch_cmd = 0.0
        self._head_yaw_cmd = 0.0
        self._head_roll_cmd = 0.0
        self._head_trail_init = False

        self._fwd_pitch_u = 0.0
        self._fwd_pitch_u_init = False

        self._fwd_trunk_u = 0.0
        self._fwd_trunk_hold_s = 0.0
        self._fwd_trunk_init = False

        self._posture_active_cached = False

        self._wiggle_phase = 0.0
        self._wiggle_last_t = time.time()

    def engage(self, now: Optional[float] = None, *, settle_s: float = 0.10) -> bool:
        """
        Enable axis-driven command synthesis.

        For now this always succeeds. The settle window lets the 8BitDo's
        bogus startup axis-correction burst drain as no-ops after the Power
        button press.
        """
        now = time.time() if now is None else float(now)

        self._reset_axis_synthesis_state(reset_commands=True)

        self._axes_engaged = True
        self._axis_settle_until_t = now + max(0.0, float(settle_s))
        return True

    def disengage(self, *, reset_commands: bool = True) -> None:
        self._axes_engaged = False
        self._axis_settle_until_t = 0.0
        self._reset_axis_synthesis_state(reset_commands=reset_commands)

    # -------- event helpers --------

    @staticmethod
    def _axis_present(ev: Any, name: str) -> bool:
        # PuddleJoy stores axis state on controller._axes
        try:
            return name in ev.controller._axes
        except Exception:
            return False

    @staticmethod
    def _trigger_to_01(v: float) -> float:
        # Accept both [-1,1] and [0,1] trigger conventions.
        return (v + 1.0) / 2.0 if v < 0.0 else v

    def pop_pressed(self) -> List[str]:
        out = list(self._pressed)
        self._pressed.clear()
        return out

    # -------- data-driven emotes --------

    def available_emotes(self) -> Tuple[str, ...]:
        return self.emote_player.names()

    def reload_emotes(self) -> Tuple[str, ...]:
        self.stop_emote()
        return self.emote_player.reload()

    def register_emote_channel_handler(self, name: str, callback) -> None:
        """Register an output callback for a non-policy emote channel.

        Callbacks receive the authored channel value while the clip is active
        and ``None`` when the channel is released.  The real-robot runtime can
        use this for ``ears`` to forward degrees to the head controller.
        """
        if not name or callback is None:
            return
        self._emote_channel_handlers.setdefault(str(name), []).append(callback)

    def _restore_emote_underlay(self) -> None:
        if not self._emote_underlay:
            return
        for idx, value in list(self._emote_underlay.items()):
            try:
                self.commands[int(idx)] = float(value)
            except Exception:
                pass
        self._emote_underlay.clear()

    def _call_emote_channel_handler(self, name: str, value: Optional[float]) -> None:
        for callback in list(self._emote_channel_handlers.get(str(name)) or []):
            try:
                callback(value)
            except TypeError:
                # Some existing callbacks may not accept Optional annotations,
                # but still accept the positional value at runtime.
                try:
                    callback(float(value) if value is not None else None)
                except Exception:
                    pass
            except Exception as exc:
                if bool(getattr(self.cfg, "emote_debug", False)):
                    print(f"[emote] output handler {name!r} failed: {exc}")

    def _release_emote_show_channels(self) -> None:
        for name in sorted(self._emote_show_active_channels):
            self._call_emote_channel_handler(name, None)
        self._emote_show_active_channels.clear()
        self._emote_last_show_values.clear()

    def _dispatch_emote_show_channels(self, sample: Any) -> None:
        # Do not gate solely on the authored frame index: when DuckDrive runs
        # faster than the clip rate, interpolated ear/show values can change
        # several times within one authored frame interval.  Value de-duplication
        # below keeps unchanged outputs quiet without dropping interpolation.
        current = {str(k): float(v) for k, v in dict(sample.show_values).items()}
        for name in sorted(self._emote_show_active_channels - set(current)):
            self._call_emote_channel_handler(name, None)
            self._emote_last_show_values.pop(name, None)

        for name, value in current.items():
            previous = self._emote_last_show_values.get(name)
            if previous is None or abs(float(previous) - float(value)) > 1e-6:
                self._call_emote_channel_handler(name, float(value))
            self._emote_last_show_values[name] = float(value)

        self._emote_show_active_channels = set(current)

    def play_emote(self, name: str, *, now: Optional[float] = None) -> bool:
        """Start/restart one named one-shot clip."""
        if now is None:
            now = self._current_update_t if self._current_update_t is not None else time.time()
        now = float(now)
        # Remove a previous frame's overlay before capturing a compatibility
        # fallback pose. Normal playback uses the live joystick pose each tick.
        self._restore_emote_underlay()
        if self.emote_player.active:
            self.emote_player.stop()
            self._release_emote_show_channels()

        played = self.emote_player.play(
            str(name),
            now=now,
            current_commands=self.commands,
        )
        # Do not reset head/trunk joystick synthesis here. The emote is now a
        # live additive overlay, so the operator's filtered/phase-backed pose
        # state must continue uninterrupted underneath it.
        return bool(played)

    def stop_emote(self) -> Optional[str]:
        self._restore_emote_underlay()
        name = self.emote_player.stop()
        self._release_emote_show_channels()
        return name

    def _apply_emote_overlay(self, now: float):
        # update() has restored the previous underlay and finished synthesizing
        # the latest joystick commands before reaching this point. Passing that
        # vector into sample() makes the animation an additive physical offset
        # from the operator's current pose instead of a trigger-time pose lock.
        sample = self.emote_player.sample(
            now=float(now),
            current_commands=self.commands,
        )
        if sample is None:
            if self._emote_show_active_channels:
                self._release_emote_show_channels()
            return self.commands

        for raw_idx, raw_value in dict(sample.command_values).items():
            idx = int(raw_idx)
            try:
                if idx < 0 or idx >= len(self.commands):
                    continue
                if idx in self._emote_passthrough_indices:
                    continue
                if idx not in self._emote_underlay:
                    self._emote_underlay[idx] = float(self.commands[idx])
                self.commands[idx] = float(raw_value)
            except Exception:
                continue

        self._dispatch_emote_show_channels(sample)
        return self.commands

    def register_axis_handler(
        self,
        name: str,
        callback,
        *,
        eps: float = 0.0,
        rate_limit_s: float = 0.0,
    ) -> None:
        """Register a callback for an axis-like event name.

        The callback will be invoked when a ControllerEvent with matching `name`
        arrives and `ev.is_axis_event()` is true.

        Args:
            name: ControllerEvent.name (e.g. "/audio/volume")
            callback: function called with (value) or (value, ev)
            eps: minimum absolute change required to fire (0 disables)
            rate_limit_s: minimum time between fires per handler (0 disables)
        """
        if not name:
            return
        self._axis_handlers.setdefault(str(name), []).append(
            {"cb": callback, "eps": float(eps), "rl": float(rate_limit_s), "last_v": None, "last_t": 0.0}
        )

    def register_button_handler(
        self,
        name: str,
        callback,
        *,
        edge: str = "press",
        consume: bool = True,
    ) -> None:
        """Register a callback for a button-like event name.

        Args:
            name: ControllerEvent.name (e.g. "/audio/mute")
            callback: function called with (pressed) or (pressed, ev)
            edge: one of {"press","release","change"}
            consume: if True, prevents this button from being added to pop_pressed()
                     via the legacy "unmapped pressed" path.
        """
        if not name:
            return
        edge = str(edge or "press").lower()
        if edge not in ("press", "release", "change"):
            edge = "press"
        self._button_handlers.setdefault(str(name), []).append({"cb": callback, "edge": edge, "consume": bool(consume)})

    def _call_handler(self, cb, *args):
        # Allow callbacks that accept either (value) or (value, ev).
        try:
            cb(*args)
        except TypeError:
            try:
                cb(args[0])
            except Exception:
                pass
        except Exception:
            pass

    def _dispatch_handlers(self, ev: Any, now: float) -> None:
        """Invoke any registered axis/button handlers for this event."""
        name = getattr(ev, "name", None)
        if not name:
            return
        name = str(name)

        # Axis handlers
        try:
            is_axis = bool(ev.is_axis_event())
        except Exception:
            is_axis = False

        if is_axis and name in self._axis_handlers:
            try:
                v = float(ev.get_axis(name))
            except Exception:
                v = float(getattr(ev, "value", 0.0) or 0.0)

            for h in list(self._axis_handlers.get(name) or []):
                eps = float(h.get("eps", 0.0) or 0.0)
                rl = float(h.get("rl", 0.0) or 0.0)

                last_v = h.get("last_v", None)
                last_t = float(h.get("last_t", 0.0) or 0.0)

                if last_v is not None and eps > 0.0 and abs(v - float(last_v)) < eps:
                    continue
                if rl > 0.0 and (now - last_t) < rl:
                    continue

                h["last_v"] = float(v)
                h["last_t"] = float(now)
                self._call_handler(h.get("cb"), float(v), ev)

        # Button handlers
        try:
            is_btn = bool(ev.is_button_event())
        except Exception:
            is_btn = False

        if is_btn and name in self._button_handlers:
            # Gesture events sometimes have value=None; treat as "pressed".
            if getattr(ev, "gesture", None):
                pressed = True
            else:
                pressed = bool(getattr(ev, "value", 0))

            for h in list(self._button_handlers.get(name) or []):
                edge = str(h.get("edge", "press")).lower()
                if edge == "press" and not pressed:
                    continue
                if edge == "release" and pressed:
                    continue
                self._call_handler(h.get("cb"), bool(pressed), ev)

    def status(self) -> Dict[str, Any]:
        state_names = set(self._toggle_states) | set(self._hold_counts)
        if self.emote_player.active_name:
            state_names.add(str(self.emote_player.active_name))
        return {
            "active": self.last_active_name,
            "strafe": self.last_strafe_source,
            "posture": bool(getattr(self, "_posture_active_cached", False) or self.is_state("posture")),
            "states": {k: self.is_state(k) for k in sorted(state_names)},
            "emote": self.emote_player.status(),
        }

    # -------- virtual state API --------

    def is_state(self, name: str) -> bool:
        if not name:
            return False
        if self.emote_player.active_name == str(name):
            return True
        if self._toggle_states.get(name, False):
            return True
        return int(self._hold_counts.get(name, 0)) > 0

    def any_state_active(self) -> bool:
        if self.emote_player.active:
            return True

        # Any latched/toggled state currently True?
        if any(bool(v) for v in self._toggle_states.values()):
            return True

        # Any hold-based (long press) state currently held?
        return any(int(n) > 0 for n in self._hold_counts.values())

    # -------- internal helpers --------

    def _is_meaningful_event(self, ev: Any, st: Dict[str, Any]) -> bool:
        # Button events always count.
        try:
            if ev.is_button_event():
                name = getattr(ev, "name", None)
                if name and str(name) in self._ignore_activity_buttons:
                    return False
                return True
        except Exception:
            pass

        # Axis events: count only if change >= eps (ignore jitter).
        try:
            if ev.is_axis_event():
                name = getattr(ev, "name", None)
                if not name:
                    return True
                if str(name) in self._ignore_activity_axes:
                    # Still update last_axis tracking but do NOT count as activity.
                    v = float(ev.get_axis(name))
                    last_axis = st["last_axis"]
                    last_axis[name] = v
                    return False
                v = float(ev.get_axis(name))
                last_axis = st["last_axis"]
                prev = last_axis.get(name)
                last_axis[name] = v
                if prev is None:
                    return True
                return abs(v - prev) >= float(self.cfg.axis_activity_eps)
        except Exception:
            return True

        return False

    def _record_pressed_unmapped(self, ev: Any) -> None:
        """Queue button-down events for *unmapped* buttons.

        Mapped buttons (those in button_map) are handled by the short/long press
        state machine to avoid conflicts (e.g. long-press shouldn't also fire
        the old 'pressed' event on down).
        """
        name = getattr(ev, "name", None)
        if not name:
            return
        if self._is_direct_posture_button(str(name)):
            return
        if str(name) in self._button_map:
            return

        # If any registered handler wants to consume this button, don't add it
        # to the legacy "pressed" queue.
        for h in (self._button_handlers.get(str(name)) or []):
            if bool(h.get("consume", True)):
                return

        def handle_pressed() -> None:
            if (
                bool(getattr(self.cfg, "emote_trigger_named_buttons", True))
                and self.emote_player.has(str(name))
            ):
                self.play_emote(str(name))
                return
            self._pressed.append(str(name))

        # Gesture events sometimes set value=None; treat those as "pressed".
        if getattr(ev, "gesture", None):
            handle_pressed()
            return

        try:
            if ev.is_button_event():
                val = getattr(ev, "value", None)
                if bool(val):
                    handle_pressed()
        except Exception:
            pass

    def _is_direct_posture_button(self, name: str) -> bool:
        """True for the plain physical posture button handled by DuckDrive.

        Controller YAMLs can simply name a button "posture".  If the main
        duckdrive config also has a button_map entry for that button, the
        button_map owns the behavior and this direct fallback stays disabled to
        avoid double-toggling.
        """
        if not bool(getattr(self.cfg, "posture_latched", True)):
            return False
        try:
            posture_button = str(getattr(self.cfg, "posture_button", "posture") or "posture")
        except Exception:
            posture_button = "posture"
        if str(name) != posture_button:
            return False
        return str(name) not in self._button_map

    def _handle_direct_posture_button(self, ev: Any) -> None:
        """Toggle posture for an unmapped physical posture button.

        This gives FrSky button 2 latch behavior without requiring a separate
        duckdrive.button_map.  A configured button_map can still override this
        with its own short/long-press behavior.
        """
        name = getattr(ev, "name", None)
        if not name or not self._is_direct_posture_button(str(name)):
            return
        try:
            if not bool(ev.is_button_event()):
                return
        except Exception:
            return
        if bool(getattr(ev, "value", 0)):
            self._toggle_state("posture")

    def _pick_active(self, now: float) -> Optional[Any]:
        # expire active if stale
        if self._active is not None:
            st = self._state.get(self._active)
            if st is None:
                self._active = None
            else:
                if (now - float(st.get("last_activity", 0.0))) > float(self.cfg.active_timeout_s):
                    self._active = None

        best = self._active
        best_t = self._state[best]["last_activity"] if best is not None else -1.0

        for c in self.controllers:
            st = self._state.get(c)
            if st is None:
                continue
            t = float(st.get("last_activity", -1.0))
            if t > best_t:
                best_t = t
                best = c
        return best

    def _on_activate(self, ev: Any, st: Dict[str, Any]) -> None:
        # If this controller lacks analog height, seed stepped height from current command output.
        if not self._axis_present(ev, "height") and self.idx_height is not None:
            try:
                st["height_state"] = float(self.commands[self.idx_height])
            except Exception:
                st["height_state"] = 0.0
            try:
                st["prev_dy"] = float(ev.get_axis("DY"))
            except Exception:
                st["prev_dy"] = 0.0

            # Clear any pending auto-repeat schedule when becoming active.
            st["taller_next_t"] = 0.0
            st["smaller_next_t"] = 0.0

        # Seed LB/RB synthetic strafe.
        if self.idx_lin_y is not None:
            st["lin_vel_y_state"] = float(self.commands[self.idx_lin_y])

        if self.idx_height is not None:
            try:
                st["posture_height_state"] = float(self.commands[self.idx_height])
            except Exception:
                st["posture_height_state"] = 0.0
            st["posture_height_next_t"] = 0.0
            st["posture_height_dir"] = 0
            st["posture_height_first_done"] = False
            st["posture_was_active"] = False

    def _edge_pressed(self, ev: Any, st: Dict[str, Any], name: str) -> bool:
        """
        Return True exactly once when the button transitions
        from not-pressed to pressed, using continuous state.
        Works even if `ev` is a cached last_event.
        """
        now_down = ev.is_pressed(name)
        prev_down = st["prev_buttons"].get(name, False)
        st["prev_buttons"][name] = now_down
        return now_down and not prev_down

    def _update_height_virtual(self, ev: Any, st: Dict[str, Any], now: float) -> float:
        """Synthesize height from buttons (taller/smaller) or DY.

        This is used only when the controller mapping does NOT provide an
        analog "height" axis.

        Desired behavior:
          - short press taller/smaller: one discrete height step
          - hold taller/smaller: keep stepping until released
        """

        step = float(self.cfg.height_step)
        delay_s = max(0.0, float(getattr(self.cfg, "height_repeat_delay_s", 0.25)))
        period_s = max(1e-3, float(getattr(self.cfg, "height_repeat_period_s", 0.08)))

        def do_step(sign: float) -> None:
            st["height_state"] = _clamp(float(st.get("height_state", 0.0)) + sign * step, -1.0, 1.0)

        # --- taller/smaller auto-repeat (time based) ---
        for btn, sign, next_key in (
            ("taller", +1.0, "taller_next_t"),
            ("smaller", -1.0, "smaller_next_t"),
        ):
            try:
                now_down = bool(ev.is_pressed(btn))
            except Exception:
                now_down = False

            prev_down = bool(st.get("prev_buttons", {}).get(btn, False))
            st.setdefault("prev_buttons", {})[btn] = now_down

            # Rising edge: step once immediately and schedule repeats.
            if now_down and (not prev_down):
                do_step(sign)
                st[next_key] = float(now) + delay_s
                continue

            # Falling edge: cancel repeats.
            if (not now_down) and prev_down:
                st[next_key] = 0.0
                continue

            # Held: repeat steps whenever the schedule elapses.
            if now_down:
                nxt = float(st.get(next_key, 0.0) or 0.0)
                if nxt <= 0.0:
                    # If we missed the rising edge for any reason, start now.
                    st[next_key] = float(now) + delay_s
                else:
                    while float(now) >= nxt:
                        do_step(sign)
                        nxt += period_s
                    st[next_key] = nxt

        dy = float(ev.get_axis("DY"))
        prev = float(st.get("prev_dy", 0.0))

        if dy > 0.5 and prev <= 0.5:
            st["height_state"] = _clamp(float(st["height_state"]) + step, -1.0, 1.0)
        elif dy < -0.5 and prev >= -0.5:
            st["height_state"] = _clamp(float(st["height_state"]) - step, -1.0, 1.0)

        st["prev_dy"] = dy
        return float(st["height_state"])

    def _derive_height(self, ev: Any, st: Dict[str, Any], now: float) -> Tuple[float, bool]:
        if self._axis_present(ev, "height"):
            return float(ev.get_axis("height")), True
        return self._update_height_virtual(ev, st, now), False

    def _derive_lin_vel_y(self, ev: Any, st: Dict[str, Any]) -> Tuple[float, str]:
        """Lateral velocity (strafe) priority:
          1) axis 'lin_vel_y'
          2) triggers: RT - LT
          3) integrate from LB/RB
        """
        if self._axis_present(ev, "lin_vel_y"):
            return float(ev.get_axis("lin_vel_y")), "axis"

        if self._axis_present(ev, "LT") and self._axis_present(ev, "RT"):
            lt = self._trigger_to_01(float(ev.get_axis("LT")))
            rt = self._trigger_to_01(float(ev.get_axis("RT")))
            return _clamp(rt - lt, -1.0, 1.0), "triggers"

        # fallback: integrate LB/RB into a virtual axis
        try:
            lb = bool(ev.is_pressed("LB"))
            rb = bool(ev.is_pressed("RB"))
        except Exception:
            lb = rb = False

        rate = float(self.cfg.lb_rb_rate)
        decay = float(self.cfg.lb_rb_decay)

        if lb and not rb:
            st["lin_vel_y_state"] = float(st["lin_vel_y_state"]) - rate
        elif rb and not lb:
            st["lin_vel_y_state"] = float(st["lin_vel_y_state"]) + rate
        else:
            st["lin_vel_y_state"] = float(st["lin_vel_y_state"]) * decay

        st["lin_vel_y_state"] = _clamp(float(st["lin_vel_y_state"]), -1.0, 1.0)
        return float(st["lin_vel_y_state"]), "lb_rb"

    def _posture_active(self, ev: Any) -> bool:
        """Posture is normally a latched virtual state.

        If posture_latched is disabled, fall back to the older hold-to-posture
        behavior for a physical button named by cfg.posture_button.
        """
        if self.is_state("posture"):
            return True
        if bool(getattr(self.cfg, "posture_latched", True)):
            return False
        try:
            posture_button = str(getattr(self.cfg, "posture_button", "posture") or "posture")
            return bool(ev.is_pressed(posture_button))
        except Exception:
            return False

    def _axis_value(self, ev: Any, name: str, default: float = 0.0) -> float:
        """Read a logical axis, returning default when the controller lacks it."""
        try:
            if self._axis_present(ev, name):
                return float(ev.get_axis(name))
        except Exception:
            pass
        return float(default)

    def _derive_head_axis(self, ev: Any, name: str, *, posture_active: bool) -> float:
        """Read head axes, allowing posture-only aliases when present.

        Most controllers expose normal head_pitch/head_yaw/head_roll axes.
        Controllers that re-use a stick for driving can instead expose
        posture_head_pitch/posture_head_yaw/posture_head_roll aliases, which
        are consumed only while posture mode is active.
        """
        posture_name = f"posture_{name}"
        if posture_active and self._axis_present(ev, posture_name):
            return self._axis_value(ev, posture_name, 0.0)
        return self._axis_value(ev, name, 0.0)

    def _reset_forward_pitch_state(self) -> None:
        """Clear the normal forward-neck/head/trunk phase state."""
        self._fwd_pitch_u = 0.0
        self._fwd_pitch_u_init = False
        self._fwd_trunk_u = 0.0
        self._fwd_trunk_hold_s = 0.0
        self._fwd_trunk_init = False

    def _derive_posture_roll(self, ev: Any) -> float:
        """Trunk roll source in posture mode.

        Priority:
          1) explicit trunk_roll axis (FrSky left pot can be aliased here)
          2) LT/RT analog triggers, as RT - LT
          3) LS_B/RS_B buttons, as RS_B - LS_B
        """
        if self._axis_present(ev, "trunk_roll"):
            return float(ev.get_axis("trunk_roll"))

        if self._axis_present(ev, "LT") and self._axis_present(ev, "RT"):
            lt = self._trigger_to_01(float(ev.get_axis("LT")))
            rt = self._trigger_to_01(float(ev.get_axis("RT")))
            return _clamp(rt - lt, -1.0, 1.0)

        try:
            left = 1.0 if bool(ev.is_pressed("LS_B")) else 0.0
            right = 1.0 if bool(ev.is_pressed("RS_B")) else 0.0
            return _clamp(right - left, -1.0, 1.0)
        except Exception:
            return 0.0

    def _update_posture_height(self, st: Dict[str, Any], pitch_raw: float, now: float) -> float:
        """Latched height control for posture mode.

        Height changes only while the left-stick pitch axis is held at an
        extreme.  The first step is intentionally delayed a little so a full
        trunk-pitch pose does not accidentally change height, then later steps
        are rate-limited so it is easy to stop on an intermediate level.
        """
        step = max(0.0, float(getattr(self.cfg, "posture_height_step", 0.25)))
        edge = _clamp(float(getattr(self.cfg, "posture_height_edge", 0.93)), 0.0, 1.0)
        release_edge = _clamp(float(getattr(self.cfg, "posture_height_release_edge", 0.82)), 0.0, edge)
        initial_delay_s = max(0.0, float(getattr(self.cfg, "posture_height_initial_delay_s", 0.22)))
        delay_s = max(0.0, float(getattr(self.cfg, "posture_height_repeat_delay_s", 0.28)))
        period_s = max(1e-3, float(getattr(self.cfg, "posture_height_repeat_period_s", 0.28)))

        cur = _clamp(float(st.get("posture_height_state", 0.0)), -1.0, 1.0)
        prev_dir = int(st.get("posture_height_dir", 0) or 0)
        next_t = float(st.get("posture_height_next_t", 0.0) or 0.0)
        first_done = bool(st.get("posture_height_first_done", False))

        # Hysteresis: enter at edge, release a little below edge so stick noise
        # near the threshold does not repeatedly re-arm the first-step delay.
        direction = 0
        if pitch_raw >= edge or (prev_dir > 0 and pitch_raw >= release_edge):
            direction = +1
        elif pitch_raw <= -edge or (prev_dir < 0 and pitch_raw <= -release_edge):
            direction = -1

        if direction == 0 or step <= 0.0:
            st["posture_height_dir"] = 0
            st["posture_height_next_t"] = 0.0
            st["posture_height_first_done"] = False
            return cur

        if direction != prev_dir:
            next_t = float(now) + initial_delay_s
            first_done = False
        elif next_t <= 0.0:
            next_t = float(now) + (period_s if first_done else initial_delay_s)

        if float(now) >= next_t:
            # Step at most once per update.  That makes posture height feel
            # like a controllable animation latch instead of a catch-up timer
            # that can skip intermediate heights after a long frame.
            cur = _clamp(cur + float(direction) * step, -1.0, 1.0)
            if not first_done:
                first_done = True
                next_t = float(now) + delay_s
            else:
                next_t = float(now) + period_s

        st["posture_height_state"] = cur
        st["posture_height_dir"] = int(direction)
        st["posture_height_next_t"] = next_t
        st["posture_height_first_done"] = bool(first_done)
        return cur

    def _sync_posture_height_state(self, st: Dict[str, Any], height: float, *, sync_virtual_height: bool) -> float:
        """Keep posture height and optional virtual height latches aligned."""
        h = _clamp(float(height), -1.0, 1.0)
        st["posture_height_state"] = h
        if sync_virtual_height:
            # Controllers without an analog height axis use height_state as the
            # normal latch.  Keep it in step with posture so releasing posture
            # preserves the animated height.
            st["height_state"] = h
            st["taller_next_t"] = 0.0
            st["smaller_next_t"] = 0.0
        return h

    # ---- virtual button mapping ----

    def _hold_inc(self, state: str) -> None:
        if not state:
            return
        self._hold_counts[state] = int(self._hold_counts.get(state, 0)) + 1

    def _hold_dec(self, state: str) -> None:
        if not state:
            return
        cur = int(self._hold_counts.get(state, 0))
        cur = max(0, cur - 1)
        if cur <= 0:
            self._hold_counts.pop(state, None)
        else:
            self._hold_counts[state] = cur

    def _neck_lock_can_enable(self) -> bool:
        if self.idx_neck_pitch is None:
            return False
        try:
            cur = float(self.commands[self.idx_neck_pitch])
        except Exception:
            return False
        min_neck = float(self._neck_lock_cfg.get("min_neck", 0.70))
        if min_neck >= 0.0:
            return cur >= min_neck
        return cur <= min_neck

    def _clear_toggle_states(self) -> None:
        """Clear all latched (toggle) virtual states.

        Note: this intentionally does *not* clear hold-based states
        (long-press holds), since those are tied to the physical button-down
        condition and are released by the button-map state machine.
        """

        # A neutral/clear action also cancels a running one-shot emote.
        self.stop_emote()

        # Fast-path: nothing else to do.
        if not self._toggle_states:
            return

        # Ensure special-case state cleanup stays consistent with _toggle_state().
        if self._toggle_states.get("neck_lock", False):
            self._neck_lock_value = 0.0

        self._toggle_states.clear()

    def _toggle_state(self, name: str) -> None:
        if not name:
            return

        # Emotes are named one-shot states. Re-triggering restarts the clip.
        if self.emote_player.has(str(name)):
            self.play_emote(str(name))
            return

        # One-shot states: these are not persistent toggles.
        # We arm them here and they auto-clear in update() once the target is reached.
        if name in ("jump", "height_center"):
            self._toggle_states[name] = True
            return

        cur = bool(self._toggle_states.get(name, False))
        new = not cur

        if name == "neck_lock":
            if new:
                if not self._neck_lock_can_enable():
                    # refuse to enable if neck isn't high enough
                    return
                # capture the current neck command as the lock point
                try:
                    self._neck_lock_value = float(self.commands[self.idx_neck_pitch])
                    self._neck_lock_head_value = float(self.commands[self.idx_head_pitch])
                except Exception:
                    self._neck_lock_value = 0.0
                self._toggle_states[name] = True
            else:
                self._toggle_states[name] = False
            return

        self._toggle_states[name] = new

    def _handle_short_press(self, button: str, cfg: Any) -> None:
        if not isinstance(cfg, dict):
            return

        # action: play a named one-shot emote
        emote = cfg.get("play_emote", cfg.get("emote"))
        if isinstance(emote, str) and emote:
            self.play_emote(emote)

        # action: toggle state
        tstate = cfg.get("toggle_state")
        if isinstance(tstate, str) and tstate:
            self._toggle_state(tstate)

        # action: emit an event name (consumer handles)
        emit = cfg.get("emit")
        if isinstance(emit, str) and emit:
            self._pressed.append(emit)

        # optional: emit the physical button name too
        if bool(cfg.get("emit_button", False)):
            self._pressed.append(str(button))

    def _update_button_map(self, now: float, joy_ev: Any) -> None:
        if not self._has_button_map:
            return

        for button, mapping in self._button_map.items():
            if not isinstance(mapping, dict):
                continue

            try:
                pressed = bool(joy_ev.is_pressed(str(button)))
            except Exception:
                pressed = False

            tr = self._btn_track.setdefault(
                button, {"down": False, "t_down": 0.0, "long_active": False, "long_state": None}
            )

            long_cfg = mapping.get("long_press")
            short_cfg = mapping.get("short_press")

            long_state = None
            hold_s = float(self.cfg.long_press_default_s)
            if isinstance(long_cfg, dict):
                ls = long_cfg.get("state")
                if isinstance(ls, str) and ls:
                    long_state = ls
                if "hold_s" in long_cfg:
                    try:
                        hold_s = float(long_cfg.get("hold_s"))
                    except Exception:
                        pass

            # rising edge
            if pressed and (not tr["down"]):
                tr["down"] = True
                tr["t_down"] = now
                tr["long_active"] = False
                tr["long_state"] = None

            # long press activation (while held)
            if pressed and tr["down"] and (not tr["long_active"]) and long_state:
                if (now - float(tr["t_down"])) >= hold_s:
                    self._hold_inc(long_state)
                    tr["long_active"] = True
                    tr["long_state"] = long_state

            # falling edge
            if (not pressed) and tr["down"]:
                # if we had a long-press state active, release it
                if tr.get("long_active") and tr.get("long_state"):
                    self._hold_dec(str(tr.get("long_state")))
                else:
                    # short press: if configured do it; else default emit the button name
                    if short_cfg is not None:
                        self._handle_short_press(str(button), short_cfg)
                    elif (
                        bool(getattr(self.cfg, "emote_trigger_named_buttons", True))
                        and self.emote_player.has(str(button))
                    ):
                        self.play_emote(str(button), now=now)
                    else:
                        self._pressed.append(str(button))

                tr["down"] = False
                tr["long_active"] = False
                tr["long_state"] = None

    # -------- public API --------

    def update(self, now: Optional[float] = None) -> Any:
        """Poll controllers (non-blocking) and update self.commands."""
        now = time.time() if now is None else float(now)
        self._current_update_t = float(now)

        # Remove the previous animation frame before joystick synthesis so the
        # smoothing state follows the operator input, not the overlay.
        self._restore_emote_underlay()

        dt = 0.0
        if self._last_update_t is not None:
            dt = max(0.0, now - float(self._last_update_t))
        self._last_update_t = now

        # 1) Poll all controllers non-blocking.
        #
        # Buttons are always allowed through to pop_pressed().
        # Axis events are drained but ignored until engage() + settle window.
        axis_command_enabled = (
            bool(self._axes_engaged)
            and now >= float(self._axis_settle_until_t)
        )

        max_events = int(self.cfg.max_events_per_update)
        if not axis_command_enabled:
            # When disabled/settling, drain aggressively so startup axis bursts
            # disappear before axes are allowed to command the robot.
            max_events = max(max_events, 64)

        for c in self.controllers:
            st = self._state.get(c)
            if st is None:
                continue

            for _ in range(max_events):
                ev = c.read_event(blocking=False)
                if ev is None:
                    break

                try:
                    is_axis = bool(ev.is_axis_event())
                except Exception:
                    is_axis = False

                try:
                    is_button = bool(ev.is_button_event())
                except Exception:
                    is_button = False

                if is_button:
                    # Buttons are not the issue. Let RLWalk see Power/Start/etc.
                    self._dispatch_handlers(ev, now)
                    self._handle_direct_posture_button(ev)
                    self._record_pressed_unmapped(ev)

                elif is_axis:
                    if axis_command_enabled:
                        # Axis side-effect handlers, if any, are also gated.
                        self._dispatch_handlers(ev, now)
                    else:
                        # Critical behavior:
                        # PuddleJoy has already updated/drained its internal
                        # axis state, but DuckDrive does not treat this as an
                        # active command source.
                        continue

                else:
                    # Unknown/non-axis/non-button event. Harmless to dispatch
                    # only once axes are enabled.
                    if axis_command_enabled:
                        self._dispatch_handlers(ev, now)
                    else:
                        continue

                if not axis_command_enabled:
                    # Button was queued, but do not cache this event as a
                    # command source and do not select an active controller yet.
                    continue

                self._last_event[c] = ev

                if self._is_meaningful_event(ev, st):
                    st["last_activity"] = now

        if not axis_command_enabled:
            # Keep policy commands neutral while axes are disabled or settling.
            self._zero_commands()
            self._active = None
            self.last_active_name = ""
            self.last_strafe_source = (
                "disabled" if not self._axes_engaged else "settling"
            )
            self._posture_active_cached = False
            self.stop_emote()
            return self.commands

        # 2) Pick active controller.
        prev_active = self._active
        self._active = self._pick_active(now)

        if self._active is None:
            self.last_active_name = ""
            self._posture_active_cached = bool(self.is_state("posture"))
            return self._apply_emote_overlay(now)

        self.last_active_name = (
            getattr(self._active, "device_name", "")
            or getattr(self._active, "name", "")
            or str(self._active)
        )

        joy_ev = self._last_event.get(self._active)
        if joy_ev is None:
            return self._apply_emote_overlay(now)
        #print(joy_ev)

        if self._active is not prev_active:
            self._on_activate(joy_ev, self._state[self._active])

        # 2.5) Update virtual state machine for mapped buttons
        self._update_button_map(now, joy_ev)

        st = self._state[self._active]

        # 3) Read raw logical inputs
        posture_active = self._posture_active(joy_ev)
        self._posture_active_cached = bool(posture_active)

        lin_x_raw = self._axis_value(joy_ev, "lin_vel_x", 0.0)

        # yaw axis naming differs between controller maps; try both
        yaw_raw = self._axis_value(joy_ev, "ang_vel", 0.0)
        if abs(yaw_raw) < 1e-12:
            yaw_raw = self._axis_value(joy_ev, "ang_vel_yaw", 0.0)

        head_pitch_raw = self._derive_head_axis(joy_ev, "head_pitch", posture_active=posture_active)
        head_yaw_raw = self._derive_head_axis(joy_ev, "head_yaw", posture_active=posture_active)
        head_roll_raw = self._derive_head_axis(joy_ev, "head_roll", posture_active=posture_active)

        lin_y_raw, strafe_src = self._derive_lin_vel_y(joy_ev, st)
        self.last_strafe_source = strafe_src

        height_raw, height_is_analog = self._derive_height(joy_ev, st, now)
        height_was_analog = bool(height_is_analog)

        if posture_active:
            # Posture has direct trunk pitch, so keep the normal forward
            # neck/head/trunk boost state from accumulating while the right
            # stick is being used as a head control.
            self._reset_forward_pitch_state()

            # Latch from the current smoothed command on entry so posture mode
            # never snaps height when the height axis is re-used for head pitch.
            if not bool(st.get("posture_was_active", False)):
                if self.idx_height is not None:
                    try:
                        st["posture_height_state"] = float(self.commands[self.idx_height])
                    except Exception:
                        st["posture_height_state"] = float(height_raw)
                else:
                    st["posture_height_state"] = float(height_raw)
                st["posture_height_next_t"] = 0.0
                st["posture_height_dir"] = 0
                st["posture_height_first_done"] = False

            height_raw = self._sync_posture_height_state(
                st,
                self._update_posture_height(st, lin_x_raw, now),
                sync_virtual_height=(not height_was_analog),
            )
            height_is_analog = False
            self.last_strafe_source = "posture"
        else:
            if bool(st.get("posture_was_active", False)) and (not height_was_analog):
                # One final sync on release covers the case where no height step
                # happened during the final posture tick.
                self._sync_posture_height_state(
                    st,
                    float(st.get("posture_height_state", height_raw)),
                    sync_virtual_height=True,
                )
            st["posture_height_next_t"] = 0.0
            st["posture_height_dir"] = 0
            st["posture_height_first_done"] = False
        st["posture_was_active"] = bool(posture_active)
        self._posture_active_cached = bool(posture_active)

        # One-shot height states: override height command to a target and then auto-clear.
        #
        # We also latch the virtual height_state so the robot stays at the target
        # after the one-shot completes (when using stepped height).
        jump_active = self.is_state("jump")
        height_center_active = (not jump_active) and self.is_state("height_center")
        height_center_target = 0.0
        if height_center_active:
            try:
                height_center_target = float(self._height_center_cfg.get("target", 0.0))
            except Exception:
                height_center_target = 0.0
            height_center_target = _clamp(height_center_target, -1.0, 1.0)

        if jump_active:
            height_raw = 1.0
            if not height_is_analog:
                st["height_state"] = 1.0
                st["taller_next_t"] = 0.0
                st["smaller_next_t"] = 0.0
        elif height_center_active:
            height_raw = height_center_target
            if not height_is_analog:
                st["height_state"] = height_center_target
                st["taller_next_t"] = 0.0
                st["smaller_next_t"] = 0.0

        if posture_active:
            height_raw = self._sync_posture_height_state(
                st,
                height_raw,
                sync_virtual_height=(not height_was_analog),
            )

        if self._edge_pressed(joy_ev, st, "faster"):
            self.imitation_phase_speed += 0.05
            print(f"imitation_phase_speed: {self.imitation_phase_speed}")
        if self._edge_pressed(joy_ev, st, "slower"):
            self.imitation_phase_speed -= 0.05
            print(f"imitation_phase_speed: {self.imitation_phase_speed}")
        if self.warbler is not None:
            if self._edge_pressed(joy_ev, st, "roll"):
                self.warbler.send_message("/warble/birdsong")

        # 4) Head trailing (time-based)
        a_head = _alpha_from_tau(dt, float(self.cfg.head_trail_tau_s)) if self._head_trail_init else 1.0
        if not self._head_trail_init:
            self._head_pitch_cmd = head_pitch_raw
            self._head_yaw_cmd = head_yaw_raw
            self._head_roll_cmd = head_roll_raw
            self._head_trail_init = True
        else:
            self._head_pitch_cmd = (1.0 - a_head) * self._head_pitch_cmd + a_head * head_pitch_raw
            self._head_yaw_cmd = (1.0 - a_head) * self._head_yaw_cmd + a_head * head_yaw_raw
            self._head_roll_cmd = (1.0 - a_head) * self._head_roll_cmd + a_head * head_roll_raw

        head_pitch = self._head_pitch_cmd
        head_yaw = self._head_yaw_cmd
        head_roll = self._head_roll_cmd

        # 5) Torso assist (kicks in only near head extremes)
        def torso_blend_component(v: float, gain: float, onset: float) -> float:
            a = abs(v)
            if a <= onset:
                return 0.0
            t = (a - onset) / (1.0 - onset)
            return gain * t * (v / a)

        trunk_pitch = torso_blend_component(head_pitch, float(self.cfg.torso_gain_pitch), float(self.cfg.torso_onset))
        trunk_yaw = torso_blend_component(head_yaw, float(self.cfg.torso_gain_yaw), float(self.cfg.torso_onset))
        trunk_roll = torso_blend_component(head_roll, float(self.cfg.torso_gain_roll), float(self.cfg.torso_onset))

        # 6) Deadzone + response curve (unit domain)
        dz = float(self.cfg.deadzone)
        exp = float(self.cfg.response_exponent)

        lin_x_u = _clamp(_shape(_apply_deadzone(lin_x_raw, dz), exp), -1.0, 1.0)
        lin_y_u = _clamp(_shape(_apply_deadzone(lin_y_raw, dz), exp), -1.0, 1.0)
        yaw_u = _clamp(_shape(_apply_deadzone(yaw_raw, dz), exp), -1.0, 1.0)

        # Suppress trunk modifiers while walking. The locomotion policy is
        # trained without trunk-command modifiers in gait, but head/neck
        # commands must remain available to the user while walking.
        walk_trunk_enable = bool(getattr(self.cfg, "disable_trunk_while_walking", True))
        walk_trunk_thresh = max(0.0, float(getattr(self.cfg, "walk_trunk_motion_thresh", 0.05)))

        def _cmd_over_thresh(idx: Optional[int], rng: Optional[Tuple[float, float]] = None) -> bool:
            if idx is None:
                return False
            try:
                cur = abs(float(self.commands[idx]))
            except Exception:
                return False
            if rng is None:
                return cur >= walk_trunk_thresh
            lo_r, hi_r = float(rng[0]), float(rng[1])
            scale_r = max(abs(lo_r), abs(hi_r), 1e-6)
            return cur >= (walk_trunk_thresh * scale_r)

        walk_trunk_suppressed = bool(
            walk_trunk_enable and (
                abs(lin_x_u) >= walk_trunk_thresh
                or abs(lin_y_u) >= walk_trunk_thresh
                or abs(yaw_u) >= walk_trunk_thresh
                or _cmd_over_thresh(self.idx_lin_x, self.range_x)
                or _cmd_over_thresh(self.idx_lin_y, self.range_y)
                or _cmd_over_thresh(self.idx_yaw, self.range_theta)
                or _cmd_over_thresh(self.idx_recover)
                or self.is_state("march")
            )
        )

        # Height: keep stepped height linear; only shape analog height
        height_u = _apply_deadzone(height_raw, dz)
        if height_is_analog:
            height_u = _shape(height_u, exp)
        height_u = _clamp(height_u, -1.0, 1.0)

        # User pitch input in unit space
        pitch_u_in = _clamp(_shape(_apply_deadzone(head_pitch, dz), exp), -1.0, 1.0)
        head_yaw_u = _clamp(_shape(_apply_deadzone(head_yaw, dz), exp), -1.0, 1.0)
        head_roll_u = _clamp(_shape(_apply_deadzone(head_roll, dz), exp), -1.0, 1.0)

        trunk_pitch_u = _clamp(_shape(_apply_deadzone(trunk_pitch, dz), exp), -1.0, 1.0)
        trunk_yaw_u = _clamp(_shape(_apply_deadzone(trunk_yaw, dz), exp), -1.0, 1.0)
        trunk_roll_u = _clamp(_shape(_apply_deadzone(trunk_roll, dz), exp), -1.0, 1.0)

        if posture_active:
            # In posture mode, base movement is disabled and the left stick is
            # reinterpreted as direct trunk pose control.  Right-stick head
            # control remains available through the usual head_* logical axes
            # or posture_head_* aliases.
            lin_x_u = 0.0
            lin_y_u = 0.0
            yaw_u = 0.0
            walk_trunk_suppressed = False

            posture_pitch_sign = -1.0 if bool(getattr(self.cfg, "posture_trunk_pitch_invert", True)) else 1.0
            trunk_pitch_u = _clamp(
                posture_pitch_sign * _shape(_apply_deadzone(lin_x_raw, dz), exp),
                -1.0,
                1.0,
            )

            # The same stick direction also arms posture height stepping at the
            # extreme.  When that height-step latch is active, level the trunk
            # pitch back toward neutral so height animation is not coupled to a
            # max forward/back trunk lean.
            if bool(getattr(self.cfg, "posture_height_level_trunk_pitch", True)):
                try:
                    posture_height_dir = int(st.get("posture_height_dir", 0) or 0)
                except Exception:
                    posture_height_dir = 0
                if posture_height_dir != 0:
                    level_blend = _clamp(
                        float(getattr(self.cfg, "posture_height_level_trunk_pitch_blend", 1.0)),
                        0.0,
                        1.0,
                    )
                    trunk_pitch_u = trunk_pitch_u * (1.0 - level_blend)

            trunk_yaw_u = _clamp(_shape(_apply_deadzone(yaw_raw, dz), exp), -1.0, 1.0)
            trunk_roll_raw = self._derive_posture_roll(joy_ev)
            trunk_roll_u = _clamp(_shape(_apply_deadzone(trunk_roll_raw, dz), exp), -1.0, 1.0)

        # 7) Neck/head/trunk pitch mapping
        #
        # Goal (for stick "up" / positive pitch input):
        #   1) Neck extends first (no trunk pitch).
        #   2) Then head pitch starts to look down.
        #   3) Then trunk pitch starts to pitch down.
        #
        # Because this is a *piecewise* mapping of the same scalar input, backing
        # off the stick automatically reverses the order:
        #   trunk returns to level first, then head, then neck.
        #
        # For stick "down" / negative pitch input, keep the existing safe-ish
        # neck/head inversion blend behavior.

        # Forward pitch phase-back + time-based trunk boost (positive pitch mapping)
        #
        # Problem we want to solve:
        #   - Neck/head "range" should remain a clean 2-phase mapping: neck -> head.
        #   - Trunk pitch is NOT part of stick range; it's an extra "boost" that starts only
        #     after the stick has been held near full-forward for a short time.
        #   - On stick release, we want the trunk to come back up FIRST (slowly), and only
        #     then allow head/neck to start returning. This avoids the trunk snapping to 0
        #     while the head/neck are still down, which can destabilize the robot.
        #
        # We implement this with:
        #   - a time-based trunk boost state (self._fwd_trunk_u)
        #   - a head/neck forward-progress scalar u_fwd with phase-back smoothing
        #   - a return "gate": while trunk boost is still > gate, we freeze u_fwd so head/neck
        #     do not start moving back yet.

        # If the user explicitly commands the other direction, clear forward state immediately.
        if pitch_u_in < 0.0:
            self._reset_forward_pitch_state()

        # --- (A) Update time-based trunk boost (NOT stick-range-based) ---
        # For trunk boost, use *raw stick* (pre head-trailing) so the dwell timer matches what the user is doing.
        pitch_u_in_raw = _clamp(_shape(_apply_deadzone(head_pitch_raw, dz), exp), -1.0, 1.0)
        u_trunk_stick = max(0.0, float(pitch_u_in_raw))  # [0,1]

        # For head/neck mapping, keep using the trailed pitch input (pitch_u_in) so the head feels "heavy".
        u_stick_pos = max(0.0, float(pitch_u_in))  # [0,1]

        trunk_enable = bool(getattr(self.cfg, "forward_trunk_enable", True)) and (not walk_trunk_suppressed) and (not posture_active)
        arm_u = _clamp(float(getattr(self.cfg, "forward_trunk_arm_u", 0.98)), 0.0, 1.0)
        hold_req = max(0.0, float(getattr(self.cfg, "forward_trunk_hold_s", 0.25)))
        trunk_u_max = _clamp(float(getattr(self.cfg, "forward_trunk_u_max", 1.0)), 0.0, 1.0)

        tau_down = max(0.0, float(getattr(self.cfg, "forward_trunk_down_tau_s", 0.35)))
        tau_up = max(0.0, float(getattr(self.cfg, "forward_trunk_up_tau_s", 0.80)))

        trunk_target = 0.0
        if trunk_enable and (u_trunk_stick > 0.0):
            # Accumulate hold time while stick is "fully forward".
            if u_trunk_stick >= arm_u:
                self._fwd_trunk_hold_s = float(self._fwd_trunk_hold_s) + float(dt)
            else:
                self._fwd_trunk_hold_s = 0.0

            # Engage trunk only after the dwell time is satisfied.
            if float(self._fwd_trunk_hold_s) >= hold_req:
                trunk_target = trunk_u_max
        else:
            self._fwd_trunk_hold_s = 0.0
            trunk_target = 0.0

        # First-order filter with asymmetric time constants (down vs up).
        if not self._fwd_trunk_init:
            self._fwd_trunk_u = float(trunk_target)
            self._fwd_trunk_init = True
        else:
            tau = tau_down if float(trunk_target) > float(self._fwd_trunk_u) else tau_up
            a_trunk = _alpha_from_tau(dt, float(tau))
            self._fwd_trunk_u = (1.0 - a_trunk) * float(self._fwd_trunk_u) + a_trunk * float(trunk_target)

        # --- (B) Decide whether forward mapping is active ---
        # Keep forward mapping active while either:
        #   - the stick is still forward, OR
        #   - u_fwd hasn't fully returned to 0, OR
        #   - trunk boost is still returning.
        if (not posture_active) and ((pitch_u_in > 0.0) or (self._fwd_pitch_u > 0.0) or (float(self._fwd_trunk_u) > 1e-6)):
            # The stick value used to drive u_fwd (head/neck) is gated during trunk return:
            # while trunk is still pitched down, we "freeze" u_fwd so head/neck don't come back yet.
            gate_u = _clamp(float(getattr(self.cfg, "forward_trunk_release_gate_u", 0.25)), 0.0, 1.0)

            u_raw = u_stick_pos  # raw stick intent for head/neck

            if (not walk_trunk_suppressed) and (float(self._fwd_trunk_u) > gate_u) and (u_raw < float(self._fwd_pitch_u)):
                # Freeze return until trunk has mostly come back up.
                u_raw = float(self._fwd_pitch_u)

            # Stick-space phase boundaries (YAML-tunable)
            u_neck_end = float(self.cfg.forward_neck_full_at)

            # Preserve the old default head-phase length (0.85 - 0.50 = 0.35) but allow tuning.
            # gain > 1 => faster head-down (shorter range), gain < 1 => slower (longer range, clamped).
            head_gain = max(1e-3, float(self.cfg.forward_head_down_gain))
            head_range = 0.35 / head_gain
            u_head_end = u_neck_end + head_range

            level_comp = 0.60   # MUST be positive: head_pitch rises with neck to keep gaze level

            u_neck_end = _clamp(u_neck_end, 1e-3, 0.999)
            u_head_end = _clamp(u_head_end, u_neck_end + 1e-3, 0.999)

            # --- phase-back smoothing on u_raw -> u_fwd (NECK+HEAD ONLY) ---
            # Attack: follow stick quickly. Release: slow down in later phases (head vs neck).
            if not self._fwd_pitch_u_init:
                self._fwd_pitch_u = u_raw
                self._fwd_pitch_u_init = True
            else:
                if u_raw >= float(self._fwd_pitch_u):
                    tau_u = float(self.cfg.forward_u_attack_tau_s)
                else:
                    u_cur = float(self._fwd_pitch_u)
                    if u_cur > u_neck_end:
                        tau_u = float(self.cfg.forward_u_release_tau_head_s)
                    else:
                        tau_u = float(self.cfg.forward_u_release_tau_neck_s)

                a_u = _alpha_from_tau(dt, tau_u)
                self._fwd_pitch_u = (1.0 - a_u) * float(self._fwd_pitch_u) + a_u * u_raw

            u = _clamp(float(self._fwd_pitch_u), 0.0, 1.0)

            # ---- Phase 1: neck extends, head compensates (positive) ----
            neck_t = _clamp(u / u_neck_end, 0.0, 1.0)
            neck_pitch_u = neck_t

            # Head rises with neck to keep gaze level (your convention)
            head_pitch_u = _clamp(level_comp * neck_t, -1.0, 1.0)

            # Trunk pitch comes ONLY from the time-based boost.
            trunk_pitch_u = _clamp(float(self._fwd_trunk_u), 0.0, 1.0)

            # ---- Phase 2: once neck is fully extended, head ramps DOWN toward -1 ----
            if u > u_neck_end:
                head_t = (u - u_neck_end) / (u_head_end - u_neck_end)
                head_t = _clamp(head_t, 0.0, 1.0)

                # Optional easing (>=1 slows the start of the head-down phase)
                head_exp = max(1e-3, float(self.cfg.forward_head_down_exponent))
                if abs(head_exp - 1.0) > 1e-6:
                    head_t = head_t ** head_exp

                # Continuous at boundary:
                # head_t=0 -> head_pitch_u = +level_comp
                # head_t=1 -> head_pitch_u = -1
                head_pitch_u = _clamp(level_comp + (-1.0 - level_comp) * head_t, -1.0, 1.0)

        else:
            # Default behavior: use pitch inversion blend to keep things reasonably safe.
            neck_pitch_u = pitch_u_in

            THRESH = float(self.cfg.pitch_invert_thresh)
            WIDTH = float(self.cfg.pitch_invert_width)
            low = THRESH - WIDTH
            high = THRESH + WIDTH

            if neck_pitch_u <= low:
                t = 0.0
            elif neck_pitch_u >= high:
                t = 1.0
            else:
                t = (neck_pitch_u - low) / (high - low)

            head_pitch_u = (1.0 - t) * neck_pitch_u + t * (-neck_pitch_u)

        # Neck lock override: freeze neck near extended position; put pitch control on head.
        if self.is_state("neck_lock") and self.idx_neck_pitch is not None:
            # Small tweak: if the user tries to command the neck below neutral (0)
            # while locked, disengage the lock so they can tuck normally.
            # if pitch_u_in < 0.0:
            #     self._toggle_states["neck_lock"] = False
            # If the neck drops below the enable threshold while locked, auto-unlock.
            if not self._neck_lock_can_enable():
                self._toggle_states["neck_lock"] = False
            else:
                locked = float(self._neck_lock_value)
                softness = float(self._neck_lock_cfg.get("neck_softness", 0.0))
                softness = _clamp(softness, 0.0, 1.0)
                neck_pitch_u = _clamp(locked + softness * (pitch_u_in - locked), -1.0, 1.0)

                head_gain = float(self._neck_lock_cfg.get("head_pitch_gain", 1.0))
                inv = bool(self._neck_lock_cfg.get("head_pitch_invert", True))
                sign = -1.0 if inv else 1.0

                # Keep the "level" head attitude when stick is released,
                # and apply stick as a delta around that baseline.
                head0 = float(self._neck_lock_head_value)
                pitch_u_lock = float(pitch_u_in)
                gate_u = _clamp(float(getattr(self.cfg, "forward_trunk_release_gate_u", 0.25)), 0.0, 1.0)
                if (not walk_trunk_suppressed) and (pitch_u_lock > 0.0) and (float(getattr(self, "_fwd_trunk_u", 0.0)) > gate_u):
                    pitch_u_lock = max(pitch_u_lock, float(getattr(self, "_fwd_pitch_u", pitch_u_lock)))
                head_pitch_u = _clamp(head0 + sign * pitch_u_lock * head_gain, -1.0, 1.0)

        # 7.5) Limit head yaw when the trunk is pitched down
        # (reduces unstable extreme down+yaw combinations without affecting neutral pitch.)
        onset = _clamp(float(getattr(self.cfg, "head_yaw_limit_pitch_onset", 1.0)), 0.0, 0.999)
        min_scale = _clamp(float(getattr(self.cfg, "head_yaw_limit_min_scale", 1.0)), 0.0, 1.0)
        pitch_down = 0.0 if walk_trunk_suppressed else max(0.0, float(trunk_pitch_u))
        if (min_scale < 1.0) and (pitch_down > onset):
            t = (pitch_down - onset) / max(1e-6, (1.0 - onset))
            t = _clamp(t, 0.0, 1.0)
            scale = 1.0 - t * (1.0 - min_scale)
            head_yaw_u = head_yaw_u * scale

        if joy_ev.is_pressed("neutral"):
            self.imitation_phase_speed = 1.0
            self._clear_toggle_states()

        # check state
        wiggle_active = self.is_state("wiggle")
        trunk_roll_active = self.is_state("trunk_roll")
        trunk_wiggle_active = self.is_state("trunk_wiggle")
        nod_active = self.is_state("nod")

        # Apply only when base motion is ~0
        cmd_eps = self.cfg.cmd_eps
        idle_ok = (
            abs(lin_x_u) < cmd_eps
            and abs(lin_y_u) < cmd_eps
            and abs(yaw_u) < cmd_eps
        )

        any_idle_anim = (not posture_active) and (wiggle_active or trunk_wiggle_active or nod_active or trunk_roll_active)

        if any_idle_anim and idle_ok and (not posture_active):
            dt_w = max(0.0, now - float(self._wiggle_last_t))
            self._wiggle_last_t = now

            # -------- select primary mode (mutually exclusive) --------
            # Priority: wiggle > trunk_wiggle > nod
            mode = None
            if wiggle_active:
                mode = "wiggle"
            elif trunk_wiggle_active:
                mode = "trunk_wiggle"
            elif nod_active:
                mode = "nod"

            # primary params
            freq = 0.0
            trunk_amp = 0.0
            head_amp = 0.0
            nod_amp = 0.0

            if mode == "wiggle":
                freq = float(self.cfg.wiggle_freq_hz)
                trunk_amp = float(self.cfg.wiggle_trunk_amp)
                head_amp = float(self.cfg.wiggle_head_amp)
            elif mode == "trunk_wiggle":
                freq = float(self.cfg.trunk_wiggle_freq_hz)
                trunk_amp = float(self.cfg.trunk_wiggle_trunk_amp)
                head_amp = float(self.cfg.trunk_wiggle_head_amp)
            elif mode == "nod":
                freq = float(self.cfg.head_nod_freq_hz)
                nod_amp = float(self.cfg.head_nod_amp)

            # trunk-roll overlay (can stack with any primary mode)
            roll_freq = float(self.cfg.trunk_roll_freq_hz)
            roll_amp = float(self.cfg.trunk_roll_trunk_amp)
            head_roll_amp = float(self.cfg.trunk_roll_head_amp)

            # -------- drive phase + apply --------
            # If only trunk_roll is active (no primary mode), use roll freq.
            drive_freq = freq if freq > 0.0 else (roll_freq if trunk_roll_active else 0.0)

            if drive_freq > 0.0 and dt_w > 0.0:
                self._wiggle_phase += 2.0 * math.pi * drive_freq * dt_w
                s = math.sin(self._wiggle_phase)

                # trunk yaw from primary trunk_amp
                if trunk_amp != 0.0:
                    trunk_yaw_u = trunk_amp * s

                # wiggle mode also yaws/rolls head
                if mode == "wiggle" and head_amp != 0.0:
                    head_yaw_u = head_amp * s
                    head_roll_u = head_yaw_u
                elif mode == "trunk_wiggle" and head_amp != 0.0:
                    if abs(head_yaw_u) <= cmd_eps:
                        head_yaw_u = head_amp * s

                # nod mode drives head pitch
                if mode == "nod" and nod_amp != 0.0:
                    head_pitch_u = nod_amp * s

                # trunk roll overlay
                if trunk_roll_active:
                    trunk_roll_u = roll_amp * s
                    head_roll_u = head_roll_amp * s
        else:
            self._wiggle_last_t = now

        # 9) Map unit inputs into policy ranges for base motion channels
        lin_x = _scale_unit_to_range(lin_x_u, self.range_x) * float(self.cfg.scale_lin_vel_x)
        lin_y = _scale_unit_to_range(lin_y_u, self.range_y) * float(self.cfg.scale_lin_vel_y)
        yaw = _scale_unit_to_range(yaw_u, self.range_theta) * float(self.cfg.scale_ang_vel_yaw)

        # Non-base channels remain in [-1,1]
        height = height_u
        neck_pitch = neck_pitch_u
        head_pitch = head_pitch_u
        head_yaw = head_yaw_u
        head_roll = head_roll_u

        # NOTE: signs match your mujoco mapping:
        # trunk_pitch/yaw get negated for commands[8]/[9], roll is not.
        trunk_pitch_cmd = -trunk_pitch_u
        trunk_yaw_cmd = -trunk_yaw_u
        trunk_roll_cmd = trunk_roll_u

        if walk_trunk_suppressed:
            trunk_pitch_cmd = 0.0
            trunk_yaw_cmd = 0.0
            trunk_roll_cmd = 0.0

        # 10) Smooth into command vector (time-based)
        a_cmd = _alpha_from_tau(dt, float(self.cfg.cmd_tau_s))
        eps = float(self.cfg.cmd_eps)

        # Height can optionally use a different smoothing alpha while one-shot height states are active.
        a_height = a_cmd
        if jump_active:
            try:
                gain = float(self._jump_cfg.get("gain", 10.0))
            except Exception:
                gain = 10.0
            gain = max(0.0, gain)
            a_height = _clamp(a_cmd * gain, 0.0, 1.0)
            print(f"a_height: {a_height}")
        elif height_center_active:
            try:
                gain = float(self._height_center_cfg.get("gain", 0.25))
            except Exception:
                gain = 0.25
            gain = max(0.0, gain)
            a_height = _clamp(a_cmd * gain, 0.0, 1.0)

        def cfg_tau(name: str, default: float) -> float:
            """Read an optional time constant from config, falling back safely."""
            try:
                val = getattr(self.cfg, name, None)
            except Exception:
                val = None
            if val is None:
                val = default
            try:
                return max(0.0, float(val))
            except Exception:
                return max(0.0, float(default))

        # Trunk channels get their own output smoothing. This catches torso
        # assist, forward-trunk boost, and idle animation changes without
        # making base/head channels feel sluggish. While walking suppression is
        # active, keep using the explicit zeroing tau so the trunk eases back
        # toward neutral at the safety-tuned rate.
        if walk_trunk_enable and walk_trunk_suppressed:
            a_trunk_pitch = a_trunk_yaw = a_trunk_roll = _alpha_from_tau(
                dt,
                cfg_tau("walk_trunk_zero_tau_s", float(self.cfg.cmd_tau_s)),
            )
        else:
            fallback_tau = float(self.cfg.cmd_tau_s)
            if walk_trunk_enable:
                fallback_tau = cfg_tau("walk_trunk_restore_tau_s", fallback_tau)
            trunk_tau = cfg_tau("trunk_tau_s", fallback_tau)
            a_trunk_pitch = _alpha_from_tau(dt, cfg_tau("trunk_pitch_tau_s", trunk_tau))
            a_trunk_yaw = _alpha_from_tau(dt, cfg_tau("trunk_yaw_tau_s", trunk_tau))
            a_trunk_roll = _alpha_from_tau(dt, cfg_tau("trunk_roll_tau_s", trunk_tau))

        def smooth(prev: float, raw: float, lo: float, hi: float) -> float:
            upd = prev * (1.0 - a_cmd) + raw * a_cmd
            upd = _clamp(upd, lo, hi)
            if abs(upd) < eps:
                upd = 0.0
            return upd

        def smooth_alpha(prev: float, raw: float, lo: float, hi: float, alpha: float) -> float:
            alpha = _clamp(float(alpha), 0.0, 1.0)
            upd = prev * (1.0 - alpha) + raw * alpha
            upd = _clamp(upd, lo, hi)
            if abs(upd) < eps:
                upd = 0.0
            return upd

        # base command clamps use policy ranges
        if self.idx_lin_x is not None:
            lo, hi = self.range_x
            self.commands[self.idx_lin_x] = smooth(float(self.commands[self.idx_lin_x]), lin_x, lo, hi)
        if self.idx_lin_y is not None:
            lo, hi = self.range_y
            self.commands[self.idx_lin_y] = smooth(float(self.commands[self.idx_lin_y]), lin_y, lo, hi)
        if self.idx_yaw is not None:
            lo, hi = self.range_theta
            self.commands[self.idx_yaw] = smooth(float(self.commands[self.idx_yaw]), yaw, lo, hi)

        # other commands: [-1,1]
        if self.idx_height is not None:
            self.commands[self.idx_height] = smooth_alpha(
                float(self.commands[self.idx_height]),
                height,
                -1.0,
                1.0,
                a_height,
            )

            # Auto-clear one-shot states once we're essentially at the target.
            if jump_active:
                self.commands[self.idx_height] = 1.0
                print(f"self.commands[self.idx_height]: {self.commands[self.idx_height]}")
                try:
                    done_eps = float(self._jump_cfg.get("done_eps", 0.02))
                except Exception:
                    done_eps = 0.02
                done_eps = max(0.0, done_eps)
                if abs(1.0 - float(self.commands[self.idx_height])) <= done_eps:
                    self._toggle_states["jump"] = False

            if height_center_active:
                try:
                    done_eps = float(self._height_center_cfg.get("done_eps", 0.02))
                except Exception:
                    done_eps = 0.02
                done_eps = max(0.0, done_eps)
                if abs(float(height_center_target) - float(self.commands[self.idx_height])) <= done_eps:
                    self._toggle_states["height_center"] = False
        if self.idx_neck_pitch is not None:
            self.commands[self.idx_neck_pitch] = smooth(float(self.commands[self.idx_neck_pitch]), neck_pitch, -1.0, 1.0)
        if self.idx_head_pitch is not None:
            self.commands[self.idx_head_pitch] = smooth(float(self.commands[self.idx_head_pitch]), head_pitch, -1.0, 1.0)
        if self.idx_head_yaw is not None:
            self.commands[self.idx_head_yaw] = smooth(float(self.commands[self.idx_head_yaw]), head_yaw, -1.0, 1.0)
        if self.idx_head_roll is not None:
            self.commands[self.idx_head_roll] = smooth(float(self.commands[self.idx_head_roll]), head_roll, -1.0, 1.0)

        if self.idx_trunk_pitch is not None:
            self.commands[self.idx_trunk_pitch] = smooth_alpha(
                float(self.commands[self.idx_trunk_pitch]),
                trunk_pitch_cmd,
                -1.0,
                1.0,
                a_trunk_pitch,
            )
        if self.idx_trunk_yaw is not None:
            self.commands[self.idx_trunk_yaw] = smooth_alpha(
                float(self.commands[self.idx_trunk_yaw]),
                trunk_yaw_cmd,
                -1.0,
                1.0,
                a_trunk_yaw,
            )
        if self.idx_trunk_roll is not None:
            self.commands[self.idx_trunk_roll] = smooth_alpha(
                float(self.commands[self.idx_trunk_roll]),
                trunk_roll_cmd,
                -1.0,
                1.0,
                a_trunk_roll,
            )

        if posture_active and bool(getattr(self.cfg, "posture_zero_recover", True)) and self.idx_recover is not None:
            try:
                self.commands[self.idx_recover] = 0.0
            except Exception:
                pass

        return self._apply_emote_overlay(now)

    def apply_walk_in_place(
        self,
        cmd,
    ):
        if not self.walk_in_place_enable:
            return cmd
        posture_active = bool(getattr(self, "_posture_active_cached", False)) or self.is_state("posture")

        # Posture can suppress march. A feet-planted emote may suppress only
        # the separate walk-in-place request; normal joystick X/Y/yaw remains
        # live. Do not clear a recovery already asserted by DuckSense: safety
        # wins over show behavior.
        feet_planted_emote = bool(
            self.emote_player.active_feet_planted
            and self.emote_player.suppress_walk_in_place_for_feet_planted
        )
        if (
            (not posture_active)
            and (not feet_planted_emote)
            and self.is_state("march")
            and (self.idx_recover is not None)
        ):
            cmd[self.idx_recover] = 1.0

        recover_active = False
        if self.idx_recover is not None:
            try:
                recover_active = abs(float(cmd[self.idx_recover])) > 0.5
            except Exception:
                recover_active = False

        # Recover / walk-in-place is still locomotion, so keep trunk commands
        # zeroed there as well. Head/neck commands are left untouched.
        if recover_active:
            for idx in (self.idx_trunk_pitch, self.idx_trunk_yaw, self.idx_trunk_roll):
                if idx is None:
                    continue
                try:
                    cmd[idx] = 0.0
                except Exception:
                    pass
        return cmd
